INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','flashcard','What are the four main causes of iron deficiency anaemia?','["1. Dietary lack (especially in infants, the poor, elderly, teenagers)\n2. Impaired absorption (gastrectomy, coeliac/sprue, achlorhydria)\n3. Increased requirement (pregnancy, infancy, adolescence)\n4. Chronic blood loss — the most common cause in the Western world (GI tract, menstruation)"]','A','Mnemonic: DAIL — Dietary, Absorption, Increased demand, Loss (bleeding). In adult males and postmenopausal women, chronic blood loss must be investigated to exclude occult GI malignancy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','flashcard','Describe the classic blood film findings in iron deficiency anaemia.','["Microcytosis (small red cells), hypochromia (enlarged central pallor >1/3 cell diameter), poikilocytosis (pencil/cigar-shaped cells), anisocytosis. In severe cases only a narrow peripheral rim of haemoglobin is visible."]','A','Pencil cells (elongated elliptocytes) are characteristic of IDA. The zone of central pallor normally occupies one-third of the cell diameter; in IDA it is greatly enlarged.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','flashcard','What are the expected lab results in established iron deficiency anaemia?','["Low serum iron, low serum ferritin (<12 µg/L), high TIBC (reflecting elevated transferrin), transferrin saturation <15%, low hepcidin. Haemoglobin and haematocrit are depressed. Bone marrow shows absence of stainable iron on Prussian blue stain."]','A','TIBC rises because the liver makes more transferrin when iron is low — inverse relationship to ferritin. Serum ferritin is the best single test for iron stores.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','flashcard','What is hepcidin and how does it change in iron deficiency?','["Hepcidin is a small peptide synthesised in the liver that inhibits ferroportin, thereby blocking iron transfer from enterocytes and macrophages into plasma. In iron deficiency, hepcidin levels fall, upregulating ferroportin and enhancing iron absorption from the duodenum."]','A','High iron → high hepcidin → traps iron in enterocytes. Low iron → low hepcidin → releases iron. Inflammation raises hepcidin (via IL-6), causing the anaemia of chronic disease.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','hard','flashcard','What is the Plummer-Vinson syndrome and what are its three components?','["Plummer-Vinson (Paterson-Kelly) syndrome is a rare triad of: 1. Microcytic hypochromic anaemia (iron deficiency), 2. Dysphagia from oesophageal webs, 3. Atrophic glossitis. It predominantly affects middle-aged women and carries an increased risk of postcricoid carcinoma."]','A','Plummer-Vinson is a rare but high-yield association: iron deficiency + oesophageal web + glossitis. Predisposes to squamous cell carcinoma of the oesophagus.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','flashcard','How is dietary iron absorbed and what factors affect it?','["Non-haem Fe³⁺ is reduced to Fe²⁺ by ferrireductases (STEAP3, duodenal cytochrome B) and transported across the apical membrane via DMT1. Haem iron enters via a separate transporter and is more efficiently absorbed (~25% vs <5% for non-haem). Absorption is enhanced by ascorbic acid, citric acid and amino acids; inhibited by tannates, carbonates, oxalates and phosphates. Fe²⁺ exits the enterocyte via ferroportin, is oxidised to Fe³⁺ by hephaestin/ceruloplasmin, and binds transferrin."]','A','Haem iron (from meat) is 5× more bioavailable than non-haem iron. Vitamin C can be given with iron supplements to enhance absorption.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','flashcard','What are the non-haematological features of severe iron deficiency?','["Koilonychia (spoon nails), alopecia, atrophic glossitis, angular cheilosis, gastric mucosal atrophy, intestinal malabsorption, pica (craving non-food substances), and periodic limb movements during sleep. These result from depletion of iron-containing enzymes throughout the body."]','A','Koilonychia is the classic nail sign — spoon-shaped nails due to iron depletion. Pica (eating clay, flour, ice) is a recognised symptom of iron deficiency.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','medium','flashcard','How does the anaemia of chronic disease differ from iron deficiency anaemia on lab testing?','["Both may be microcytic/normocytic and hypochromic. Key differences: Anaemia of chronic disease (ACD) has low serum iron but also LOW TIBC and NORMAL/HIGH ferritin and HIGH hepcidin (driven by IL-6), with abundant storage iron in marrow macrophages. IDA has low serum iron, HIGH TIBC, LOW ferritin, LOW hepcidin, and absent marrow iron."]','A','In ACD, iron is trapped in macrophages by high hepcidin; in IDA, iron stores are genuinely depleted. Ferritin is an acute-phase reactant and can be falsely elevated in inflammation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','hard','flashcard','What is the sequence of laboratory changes as iron deficiency develops?','["Stage 1 (pre-latent): Iron stores depleted; serum ferritin falls; haemoglobin and serum iron still normal.\nStage 2 (latent): Serum iron falls, TIBC rises, transferrin saturation falls <15%; still no anaemia.\nStage 3 (overt IDA): Haemoglobin falls; microcytic hypochromic anaemia appears; erythropoiesis becomes iron-restricted."]','A','Ferritin falls first, anaemia appears last. Bone marrow Prussian blue stain shows absent storage iron even before blood changes are maximal.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Iron Deficiency Anaemia','easy','flashcard','How does the body store iron and what are the main storage forms?','["Iron is stored as ferritin (ubiquitous, soluble protein-iron complex; highest in liver, spleen, bone marrow, skeletal muscle) and haemosiderin (aggregated, partially degraded ferritin in lysosomes; chemically reactive; stains blue-black with Prussian blue/Perls'' stain). Total body iron ~2.5 g (women) to 6 g (men); 80% functional (haemoglobin), 15–20% storage."]','A','Haemosiderin = Prussian blue positive on staining. Normal individuals have only trace haemosiderin; overload patients accumulate large amounts.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','flashcard','What is the common pathological mechanism underlying all megaloblastic anaemias?','["Impaired DNA synthesis due to deficiency of vitamin B12 or folate (or both), leading to ineffective haematopoiesis and nuclear-cytoplasmic asynchrony. DNA synthesis lags while RNA and protein synthesis (cytoplasm/haemoglobin) proceed normally, producing abnormally large cells with immature-appearing nuclei."]','A','DNA synthesis impaired → nucleus cannot divide properly → large cells with finely distributed chromatin. Affects all rapidly dividing cells: bone marrow, GI mucosa.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','flashcard','Describe the peripheral blood film findings in megaloblastic anaemia.','["Macrocytosis (large oval red cells — macro-ovalocytes), anisocytosis, poikilocytosis, low reticulocyte count. Neutrophils are hypersegmented (≥5 nuclear lobes; normally 3–4 lobes). Occasionally nucleated red cells in severe anaemia. MCHC is not elevated despite apparent ''hyperchromia''."]','A','Hypersegmented neutrophils are highly characteristic — finding even one neutrophil with ≥6 lobes is significant. Macro-ovalocytes (not just round macrocytes) are the typical RBC shape.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','flashcard','What causes pernicious anaemia and what are the types of autoantibodies involved?','["Pernicious anaemia is caused by autoimmune atrophic gastritis destroying gastric parietal cells, impairing intrinsic factor (IF) production, which is required for ileal B12 absorption. Three autoantibodies: Type I (75%) — blocks B12 binding to IF; Type II — prevents IF-B12 complex binding to ileal receptor (cubilin); Type III (85–90%) — against gastric proton pump (α/β subunits of H⁺/K⁺-ATPase). Associated with autoimmune thyroiditis and adrenalitis."]','A','Pernicious anaemia = auto-immune gastritis + IF deficiency + B12 deficiency. Type III antibody (anti-parietal cell) is most common but least specific.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','hard','flashcard','Describe the neurological manifestations of vitamin B12 deficiency and explain the underlying mechanism.','["Subacute combined degeneration of the spinal cord: demyelination of the dorsal columns (posterior) and lateral corticospinal tracts, causing spastic paraparesis, sensory ataxia (loss of vibration and proprioception), and severe paresthesias in lower limbs. Mechanism: B12 is required for conversion of methylmalonyl-CoA to succinyl-CoA; deficiency leads to accumulation of methylmalonate and propionate, with incorporation of abnormal fatty acids into neuronal lipids and subsequent myelin breakdown."]','A','B12 deficiency → methylmalonic acid ↑ → abnormal myelin. Folate does NOT prevent (may worsen) neurological deficit. Always exclude B12 deficiency before giving folate alone.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','flashcard','How does vitamin B12 deficiency impair folate metabolism and DNA synthesis?','["B12 is required for methionine synthase to convert homocysteine to methionine. In this reaction, N5-methyl-FH4 (main plasma folate form) donates its methyl group and is converted to FH4. Without B12, folate is ''trapped'' as N5-methyl-FH4 and unavailable for conversion to N5,10-methylene-FH4, which is needed by thymidylate synthetase for dTMP synthesis → impaired DNA synthesis. This is the ''methyl-folate trap'' hypothesis."]','A','B12 deficiency causes a functional folate deficiency via the methyl-folate trap. Serum homocysteine is elevated in BOTH B12 and folate deficiency; methylmalonic acid is elevated only in B12 deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','flashcard','What are the main causes of vitamin B12 deficiency other than pernicious anaemia?','["1. Strict vegan diet (no animal products)\n2. Gastrectomy (loss of IF-secreting parietal cells)\n3. Ileal resection or disease (loss of IF-B12 absorption site)\n4. Pancreatic exocrine insufficiency (B12 cannot be released from haptocorrin)\n5. Fish tapeworm (Diphyllobothrium latum) competing for B12\n6. Achlorhydria (B12 not released from food protein)\n7. Increased demand: pregnancy, hyperthyroidism, cancer"]','A','Normal B12 stores last 3–5 years. Deficiency takes years to develop on a vegan diet but can be faster after gastrectomy combined with depleted stores.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','easy','flashcard','What are the main causes of folate deficiency?','["1. Decreased intake: poor diet (alcoholics, elderly, indigent), cooking destroys 95% of folate in food\n2. Increased requirement: pregnancy, infancy, haemolytic anaemia, disseminated cancer\n3. Impaired utilisation/metabolism: methotrexate (inhibits dihydrofolate reductase), phenytoin, oral contraceptives\n4. Malabsorption: coeliac disease, diffuse small bowel disease"]','A','Body folate stores last only weeks to months (vs years for B12). Folate deficiency in pregnancy causes neural tube defects → supplement periconceptionally. Neurological features are ABSENT in folate deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','flashcard','How can B12 deficiency be distinguished from folate deficiency on laboratory testing?','["Both: macrocytic anaemia, hypersegmented neutrophils, elevated serum homocysteine.\nOnly in B12 deficiency: elevated serum methylmalonic acid (MMA), low serum B12, neurological manifestations (subacute combined degeneration).\nOnly in folate deficiency: low serum/red cell folate, normal MMA, no neurological deficit."]','A','Elevated MMA is the key distinguishing feature of B12 deficiency. Normal MMA rules out B12 deficiency as the cause. Always check BOTH before treating.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','medium','flashcard','Describe the bone marrow findings in megaloblastic anaemia.','["Hypercellular marrow replacing fatty marrow. Megaloblastic erythroid precursors: large promegaloblasts with deeply basophilic cytoplasm, prominent nucleoli, finely distributed (''open'') chromatin — nuclear maturation lags behind cytoplasmic haemoglobinisation (nuclear-cytoplasmic asynchrony). Giant metamyelocytes and band forms in myeloid series. Abnormally large, multilobate megakaryocytes. Ineffective erythropoiesis with intramedullary apoptosis → pancytopenia despite hypercellular marrow."]','A','Key concept: hypercellular marrow + pancytopenia = ineffective haematopoiesis. Cells die in the marrow before reaching circulation.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Megaloblastic Anaemia','hard','flashcard','What are the diagnostic criteria for pernicious anaemia and how is it confirmed?','["1. Moderate-to-severe megaloblastic anaemia\n2. Leukopenia with hypersegmented neutrophils\n3. Low serum vitamin B12\n4. Elevated serum homocysteine AND methylmalonic acid\n5. Positive anti-intrinsic factor antibodies (highly specific for PA)\nConfirmed by: reticulocytosis and rising haematocrit within 5 days of parenteral B12. Schilling test (now rarely used) demonstrated failure of oral B12 absorption corrected by IF."]','A','Anti-IF antibodies are highly specific (not sensitive) for PA. Anti-parietal cell antibodies are sensitive but non-specific. Patients have increased risk of gastric carcinoma.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','flashcard','What are the key differences between intravascular and extravascular haemolysis?','["Extravascular haemolysis (most common): premature destruction of red cells by macrophages in spleen, liver, bone marrow. Causes: reduced RBC deformability. Features: anaemia, splenomegaly, jaundice (unconjugated), reduced haptoglobin, no haemoglobinuria. Benefits from splenectomy.\n\nIntravascular haemolysis (less common): RBC lysis within blood vessels. Causes: complement, mechanical trauma, toxins, parasites. Features: anaemia, haemoglobinaemia, haemoglobinuria (red-brown urine), haemosiderinuria, methaemoglobinaemia, NO splenomegaly."]','A','Key marker of intravascular haemolysis: free haemoglobin in plasma/urine. Key marker of extravascular: splenomegaly. Both cause ↓haptoglobin and unconjugated hyperbilirubinaemia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','flashcard','What is hereditary spherocytosis and what is its molecular basis?','["Hereditary spherocytosis (HS) is an inherited defect in red cell membrane skeleton proteins causing spheroid, less deformable RBCs that are sequestered and destroyed in the spleen. Mutations affect α-spectrin, β-spectrin, ankyrin, band 3, or band 4.2 — weakening the linkages that tether the lipid bilayer to the underlying spectrin-actin skeleton. The resulting instability causes membrane vesiculation and loss of surface area, forcing cells into a spherical shape. Autosomal dominant in ~75% of cases."]','A','Normal RBC shape (biconcave disc) depends on spectrin-ankyrin-band 3 interactions. Loss of membrane → sphere → trapped in splenic cords → phagocytosed. Splenectomy is curative.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','flashcard','What are the clinical features and complications of hereditary spherocytosis?','["Triad: anaemia (mild to moderate), splenomegaly, jaundice (unconjugated). Severity varies widely. Complications: 1. Aplastic crises — triggered by parvovirus B19 infection of erythroid progenitors; 2. Haemolytic crises — during infections; 3. Megaloblastic crises — folate depletion from chronic haemolysis; 4. Pigment gallstones (cholelithiasis) from chronic bilirubin overproduction. 20–30% are so mild as to be virtually asymptomatic."]','A','Aplastic crisis from parvovirus B19 is the most dangerous acute complication — sudden drop in Hb due to cessation of erythropoiesis. Splenectomy eliminates haemolysis but not the spherocytes.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','hard','flashcard','Explain the pathogenesis of G6PD deficiency and what triggers haemolytic episodes.','["G6PD (glucose-6-phosphate dehydrogenase) catalyses the first step of the hexose monophosphate shunt, generating NADPH. NADPH is required to reduce glutathione (via glutathione reductase), protecting RBCs against oxidant damage. G6PD deficiency → inadequate NADPH → oxidised haemoglobin denatures and precipitates as Heinz bodies → membrane damage → intravascular and extravascular haemolysis. X-linked; predominantly affects males. Triggers: infections (most common), oxidant drugs (primaquine, dapsone, nitrofurantoin), fava beans."]','A','G6PD deficiency = inability to handle oxidant stress. Heinz bodies = denatured Hb precipitates (seen with special stains). Bite cells seen on blood film (macrophages bite out Heinz bodies).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','flashcard','What is autoimmune haemolytic anaemia (AIHA) and how is it classified?','["AIHA is caused by autoantibodies against red cell surface antigens, leading to their destruction. Classification by thermal reactivity:\n1. Warm AIHA (most common, ~80%): IgG antibodies active at 37°C; extravascular haemolysis via splenic macrophages; associated with SLE, CLL, drugs (methyldopa). Responds to steroids/splenectomy.\n2. Cold AIHA: IgM antibodies (cold agglutinins) active at <37°C; fix complement → intravascular haemolysis; associated with Mycoplasma pneumoniae, infectious mononucleosis, lymphoma."]','A','Diagnosis by direct Coombs (DAT) test: warm AIHA shows IgG ± complement on RBC surface; cold AIHA shows complement (C3d) only. Warm = Warm IgG; Cold = Cold IgM.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','flashcard','What are the general laboratory findings shared by all haemolytic anaemias?','["1. Anaemia with reticulocytosis (compensatory erythroid hyperplasia)\n2. Unconjugated (indirect) hyperbilirubinaemia → jaundice\n3. Low or absent serum haptoglobin\n4. Elevated LDH (from lysed RBCs)\n5. Urobilinogen in urine and faeces\n6. Bone marrow: erythroid hyperplasia (normoblasts)\n7. Risk of pigment gallstones with chronic haemolysis\nIn intravascular: also haemoglobinaemia, haemoglobinuria, haemosiderinuria"]','A','Reticulocytosis + unconjugated bilirubin + low haptoglobin = haemolytic anaemia triad. LDH elevated because it is released from destroyed RBCs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','flashcard','What causes microangiopathic haemolytic anaemia (MAHA) and what is seen on blood film?','["MAHA results from mechanical fragmentation of RBCs as they are forced through narrowed or obstructed small vessels (fibrin strands in microthrombi, prosthetic valves, malignant hypertension). Blood film shows schistocytes (fragmented red cells, helmet cells, triangular cells). MAHA occurs in TTP, HUS, DIC, HELLP syndrome, and prosthetic valve haemolysis."]','A','Schistocytes on blood film + thrombocytopenia = think MAHA. The RBCs are cut by fibrin strands stretched across damaged microvessels.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','hard','flashcard','What is paroxysmal nocturnal haemoglobinuria (PNH) and why does it cause intravascular haemolysis?','["PNH is an acquired clonal disorder caused by somatic mutation in the PIGA gene in a haematopoietic stem cell, leading to deficiency of GPI-anchored proteins including CD55 (decay-accelerating factor) and CD59 (protectin). These proteins normally inhibit complement on the RBC surface. Without them, complement-mediated lysis occurs, causing episodic intravascular haemolysis (classically at night when respiratory acidosis slightly activates complement). Features: haemolytic anaemia, haemoglobinuria, venous thrombosis, cytopenias. Strongly associated with aplastic anaemia."]','A','PNH = GPI anchor defect → no CD55/CD59 → complement destroys RBCs. Diagnosed by flow cytometry showing GPI-deficient blood cells. Ham''s acid lysis test is older method.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','easy','flashcard','What are the two broad mechanisms by which haemolytic anaemias are classified?','["1. Intrinsic (corpuscular) defects — abnormalities within the red cell itself: membrane defects (hereditary spherocytosis, elliptocytosis), enzyme defects (G6PD, pyruvate kinase deficiency), haemoglobin defects (sickle cell disease, thalassaemia). Usually inherited.\n2. Extrinsic defects — factors outside the RBC: immune (AIHA), microangiopathic (TTP, HUS, DIC), infections (malaria, Clostridium), drugs, hypersplenism. Usually acquired."]','A','Intrinsic = inside the RBC (mostly inherited). Extrinsic = outside the RBC (mostly acquired). Exception: PNH is an acquired intrinsic defect.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Haemolytic Anaemias','medium','flashcard','What are the consequences of chronic intravascular haemolysis on renal function?','["Free haemoglobin filtered by the glomerulus is reabsorbed by proximal tubular cells, which catabolise it and accumulate iron as haemosiderin within tubular cells (renal haemosiderosis). Haemosiderinuria results when tubular capacity is exceeded. Chronic haemoglobin exposure can cause renal tubular damage. Free Hb also scavenges nitric oxide, causing vasoconstriction and smooth muscle dystonias (dysphagia, erectile dysfunction, abdominal pain)."]','A','Renal haemosiderosis can be detected in the urine sediment (tubular cells containing haemosiderin, staining blue with Prussian blue). Most relevant clinically in PNH and chronic intravascular haemolysis.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','easy','flashcard','What is the molecular basis of sickle cell disease?','["A point mutation in the 6th codon of the β-globin gene substitutes valine for glutamic acid (GAG→GTG), producing sickle haemoglobin (HbS, α₂βS₂). When deoxygenated, HbS molecules polymerise into long needle-like fibres within RBCs, distorting them into a sickle or holly-leaf shape. Homozygotes (HbSS) have sickle cell disease; heterozygotes (HbAS) have largely asymptomatic sickle cell trait."]','A','Glu→Val at position 6 of β-globin: a negatively charged residue becomes hydrophobic, allowing deoxygenated HbS monomers to stack. HbA and HbF both inhibit polymerisation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','flashcard','What factors increase or decrease the tendency for HbS polymerisation?','["Factors INCREASING sickling: deoxygenation, low pH (acidosis), dehydration (increased MCHC), high HbS concentration, coexistent HbC (HbSC cells lose water and concentrate HbS), slow microvascular transit time (spleen, bone marrow, inflamed vessels).\nFactors DECREASING sickling: presence of HbA (inhibits polymerisation), high HbF (strongly inhibits — infants asymptomatic until 5–6 months), co-existent α-thalassemia (reduces Hb concentration), well-oxygenated states, adequate hydration."]','A','HbF is the most potent inhibitor of sickling — basis of hydroxyurea therapy, which raises HbF levels. Patients with hereditary persistence of HbF have very mild disease.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','flashcard','Describe the peripheral blood film findings in sickle cell anaemia.','["Irreversibly sickled cells (elongated, crescent-shaped), target cells (from RBC dehydration), reticulocytosis, Howell-Jolly bodies (nuclear remnants in RBCs, indicating functional asplenia), polychromasia. Bone marrow shows erythroid hyperplasia. Skull radiograph shows ''crew-cut'' appearance from marrow expansion."]','A','Howell-Jolly bodies are normally removed by the spleen; their presence on blood film indicates hyposplenism or asplenia — a hallmark of chronic sickle cell disease in adults.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','hard','flashcard','What are vaso-occlusive crises in sickle cell disease and what triggers them?','["Vaso-occlusive (painful) crises occur when sickled RBCs block microvascular beds causing ischaemia and infarction. Triggers: infection/inflammation (most common — upregulates adhesion molecules on endothelium and activates leukocytes), dehydration, cold, hypoxia, acidosis. Sickle RBCs overexpress adhesion molecules and adhere to activated endothelium; stasis allows deoxygenation and more sickling (vicious cycle). Nitric oxide depletion by free Hb causes vasoconstriction and platelet aggregation, worsening occlusion."]','A','Inflammation → endothelial activation → RBC adhesion → stasis → deoxygenation → more sickling → more occlusion. This positive feedback cycle underlies painful crises.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','flashcard','What are the different types of crises in sickle cell disease?','["1. Vaso-occlusive (painful) crisis — most common; ischaemia in bone marrow, spleen, lung, brain, priapism\n2. Acute chest syndrome — vaso-occlusion/infection in pulmonary vessels; fever, chest pain, hypoxia; can be fatal\n3. Sequestration crisis — children with intact spleens; massive splenic trapping of sickled RBCs → sudden splenomegaly, hypovolaemia, shock\n4. Aplastic crisis — parvovirus B19 infects erythroid progenitors → sudden worsening anaemia\n5. Haemolytic crisis — acute exacerbation of haemolysis, often with infection"]','A','The 5 crises: VOC, Chest, Sequestration, Aplastic, Haemolytic. Parvovirus B19 causes aplastic crisis (same as in hereditary spherocytosis).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','hard','flashcard','What chronic organ damage occurs in sickle cell disease?','["Spleen: progressive autosplenectomy from chronic erythrostasis → infarction → fibrosis and shrinkage (''autosplenectomy''); increased susceptibility to encapsulated organisms (Streptococcus pneumoniae, Haemophilus influenzae) → prophylactic penicillin and vaccination.\nBone: expansion of marrow (crew-cut skull), avascular necrosis of femoral/humeral heads.\nKidney: renal medullary infarcts → hyposthenuria (inability to concentrate urine); renal papillary necrosis.\nRetina: vascular occlusion → retinopathy, blindness.\nCNS: stroke from adhesion of sickled cells to arterial endothelium.\nLung: pulmonary hypertension from repeated acute chest episodes."]','A','Autosplenectomy = functional asplenia without surgical removal. Occurs in virtually all adults with HbSS. Results in susceptibility to encapsulated bacteria — give Pneumovax, Hib vaccine, prophylactic penicillin.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','easy','flashcard','What is HbSC disease and how does it differ from HbSS?','["HbSC disease occurs in compound heterozygotes who inherit one HbS gene and one HbC gene (HbC = lysine substituted for glutamate at β-globin position 6). HbSC cells contain 50% HbS (vs 40% in HbAS), and HbC causes RBCs to lose salt and water, concentrating HbS and favouring polymerisation. HbSC disease is a symptomatic sickling disorder but milder than HbSS sickle cell disease. About 1 in 1250 African Americans are HbSC."]','A','HbSC = compound heterozygote (not homozygote). Both HbS genes are not required to cause disease — HbC worsens sickling by concentrating HbS. Milder than HbSS but NOT benign (retinopathy is common).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','flashcard','How is sickle cell disease diagnosed?','["1. Clinical suspicion + blood film (irreversibly sickled cells, target cells, Howell-Jolly bodies)\n2. Sickling test: mix blood with oxygen-consuming reagent (sodium metabisulfite) → induces sickling if HbS present\n3. Haemoglobin electrophoresis: confirms HbS, excludes HbSC disease and other variants; in HbSS → predominantly HbS with HbF, no HbA\n4. Prenatal diagnosis: fetal DNA analysis (amniocentesis or chorionic villus sampling) for point mutation"]','A','HPLC or electrophoresis distinguishes HbSS (HbS + HbF only), HbSC (HbS + HbC), and HbAS (HbS + HbA). Neonatal screening identifies HbSS before symptoms.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','hard','flashcard','Why does sickle cell trait confer partial protection against falciparum malaria?','["In HbAS cells, metabolically active intracellular Plasmodium falciparum parasites consume O₂ and lower pH, triggering sickling of infected RBCs. These distorted, stiff cells are cleared more rapidly by phagocytes in the spleen and liver, keeping parasite loads down. Additionally, sickling impairs formation of PfEMP-1 membrane knobs that are essential for cytoadherence of infected RBCs to endothelium (critical in cerebral malaria). AS children have lower parasite densities and lower mortality from malaria than AA children."]','A','This is a textbook example of balanced polymorphism: HbS is harmful in homozygotes but provides survival advantage against malaria in heterozygotes, explaining its high prevalence in malaria-endemic regions.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Sickle Cell Disease','medium','flashcard','What are the skeletal manifestations of sickle cell disease and their pathological basis?','["Chronic bone marrow expansion (erythroid hyperplasia compensating for haemolysis) causes: bossing of the skull producing a ''crew-cut'' appearance on X-ray (perpendicular striations from expanded marrow trabeculae), prominent cheekbones, and thickening of calvarium. Avascular necrosis (osteonecrosis) of the femoral and humeral heads results from vascular occlusion in these watershed areas. Growth retardation from chronic anaemia. Dactylitis (hand-foot syndrome) — vaso-occlusive infarction of small bones in the hands and feet, often the earliest manifestation in infants."]','A','''Crew-cut'' skull = marrow expansion on X-ray. Dactylitis (painful swollen hands/feet) is often the first presentation in infants aged 6 months–2 years.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','easy','flashcard','What is the fundamental pathophysiological difference between α-thalassaemia and β-thalassaemia?','["Both are caused by deficient globin chain synthesis leading to HbA (α₂β₂) deficiency and haemolytic anaemia. In β-thalassaemia: deficient β-chain synthesis → excess unpaired α-chains precipitate within erythroid precursors → membrane damage → intramedullary apoptosis (ineffective erythropoiesis) → severe anaemia. α-chains are the most damaging precipitates. In α-thalassaemia: deficient α-chain synthesis → excess β-chains (form HbH, β₄ tetramers in adults) or γ-chains (form Hb Bart''s, γ₄ tetramers in foetuses). β- and γ-tetramers are less damaging but have very high O₂ affinity → poor O₂ delivery."]','A','α-thalassaemia: excess β-chains → HbH (β₄). β-thalassaemia: excess α-chains → precipitates → intramedullary haemolysis. The α-chain excess in β-thal is more destructive than the β-chain excess in α-thal.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','flashcard','Describe the genotypes and clinical severity of β-thalassaemia.','["β⁰ mutations: absent β-globin synthesis (stop codons, frameshifts)\nβ⁺ mutations: reduced β-globin synthesis (splicing or promoter mutations)\n\nClinical syndromes:\n• β-thalassaemia major (Cooley''s anaemia): β⁰/β⁰, β⁺/β⁰, β⁺/β⁺ — severe transfusion-dependent anaemia, Hb 3–6 g/dL; presents at 6–9 months when HbF→HbA switch occurs\n• β-thalassaemia intermedia: β⁺/β⁺ or mild β⁺/β⁰ — moderate anaemia, not always transfusion-dependent\n• β-thalassaemia minor/trait: β⁰/β or β⁺/β — mild microcytic hypochromic anaemia, often asymptomatic; elevated HbA₂ is the diagnostic marker"]','A','Thalassaemia trait (minor): Hb electrophoresis shows HbA₂ >3.5% — this is the key diagnostic finding. Often confused with IDA; distinguish by ferritin (normal in trait) and HbA₂.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','flashcard','What are the clinical and morphological features of β-thalassaemia major?','["Severe anaemia (Hb 3–6 g/dL) appearing at 6–9 months; HbF markedly elevated; HbA absent/markedly reduced. Blood film: severe anisocytosis, poikilocytosis, microcytosis, hypochromia, target cells, basophilic stippling, fragmented RBCs. Massive erythroid hyperplasia in marrow → cortical bone erosion, skeletal deformities (''hair-on-end'' skull, prominent malar eminences, ''chipmunk face''), frontal bossing. Extramedullary haematopoiesis (liver, spleen, lymph nodes, paravertebral masses). Massive hepatosplenomegaly. Iron overload from transfusions and excessive GI absorption → secondary haemochromatosis (heart, liver, endocrine glands)."]','A','''Hair-on-end'' skull on X-ray = β-thalassaemia major (also seen in sickle cell disease). Iron overload from repeated transfusions is the main cause of death — treat with iron chelation (deferoxamine).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','hard','flashcard','Describe the four α-thalassaemia genotypes and their clinical manifestations.','["Normal: αα/αα (4 functional α-globin genes on chromosome 16)\n1. Silent carrier (−α/αα): 1 gene deleted → completely asymptomatic, normal blood indices\n2. α-thalassaemia trait (−α/−α or ‒‒/αα): 2 genes deleted → mild microcytic hypochromic anaemia, asymptomatic\n3. HbH disease (‒‒/−α): 3 genes deleted → moderate-to-severe haemolytic anaemia; excess β-chains form HbH (β₄) tetramers; HbH precipitates as cells age → Heinz body-like inclusions → splenic destruction\n4. Hb Bart''s hydrops fetalis (‒‒/‒‒): all 4 genes deleted → no α-chains; Hb Bart''s (γ₄) formed; extremely high O₂ affinity → severe foetal hypoxia → hydrops fetalis → stillbirth or death shortly after birth"]','A','4 α-globin genes: lose 1=silent, 2=trait, 3=HbH disease, 4=hydrops fetalis (lethal). Hb Bart''s γ₄ has near-zero O₂ delivery to tissues.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','flashcard','What are the findings on Hb electrophoresis in thalassaemia syndromes?','["β-thalassaemia major: HbF markedly elevated (predominant Hb), HbA absent (β⁰) or very low (β⁺), HbA₂ variable.\nβ-thalassaemia minor/trait: HbA₂ elevated (>3.5%) — this is the KEY diagnostic marker; HbF mildly elevated (1–3%); HbA present.\nα-thalassaemia trait: electrophoresis is NORMAL in adults; diagnosis requires molecular testing. In neonates: Hb Bart''s (γ₄) detected.\nHbH disease: HbH (β₄) detected on electrophoresis; Hb Bart''s present in neonates.\nHb Bart''s hydrops fetalis: predominantly Hb Bart''s (γ₄), no HbA or HbF."]','A','Elevated HbA₂ is the hallmark of β-thalassaemia trait — the most clinically important finding to recognise. α-thalassaemia trait has a normal adult electrophoresis — easily missed without molecular testing.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','hard','flashcard','Why does ineffective erythropoiesis in β-thalassaemia major cause iron overload even without transfusion?','["Ineffective erythropoiesis suppresses hepatic hepcidin production through poorly understood signals (possibly GDF15, erythroferrone from erythroid precursors). Low hepcidin → ferroportin activity increased → enhanced GI iron absorption. This occurs even when body iron stores are already elevated, creating a paradox where the starving erythroid marrow drives further iron absorption. Iron accumulates in parenchymal organs (liver, heart, endocrine glands). Combined with transfusional iron load, this leads to severe secondary haemochromatosis."]','A','Ineffective erythropoiesis overrides normal feedback: even when iron stores are HIGH, low hepcidin drives continued iron absorption. This is why β-thal major patients need iron chelation (deferoxamine or deferasirox) regardless of transfusion history.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','easy','flashcard','In which geographical regions are the thalassaemias most prevalent and why?','["Thalassaemias are endemic in Mediterranean countries (''thalassa'' = sea in Greek), the Middle East, tropical Africa, the Indian subcontinent, and Southeast Asia — regions historically endemic for falciparum malaria. Heterozygous carriers are partially protected against malaria (similar to sickle cell trait), providing strong Darwinian selection. This explains the high carrier frequency (up to 25% in some populations)."]','A','Thalassaemia and sickle cell trait are both examples of balanced polymorphism maintained by malaria selection. All three major RBC disorders prevalent in tropics (thalassaemia, SCD, G6PD deficiency) confer partial malaria protection.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','flashcard','Why does co-existent α-thalassaemia improve the clinical course of β-thalassaemia major?','["The fundamental pathology of β-thalassaemia is the EXCESS of unpaired α-chains, which precipitate and destroy erythroid precursors. Co-existent α-thalassaemia reduces the amount of α-chain synthesised, lessening the imbalance between α- and β-chains. This decreases the severity of ineffective erythropoiesis and red cell haemolysis, improving the clinical course. Conversely, β-thalassaemia heterozygotes with extra α-globin gene duplications have WORSENED disease."]','A','The clinical severity of β-thalassaemia is proportional to the degree of chain imbalance. Any factor that reduces unpaired α-chains (like α-thal deletion) improves the disease.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','hard','flashcard','What is the molecular basis of β-thalassaemia mutations and give examples of each type?','["More than 100 mutations identified, all on chromosome 11 in the β-globin gene:\n1. Splicing mutations (most common cause of β⁺-thal): usually in introns; create ectopic splice sites → abnormal + some normal mRNA\n2. Promoter region mutations (β⁺-thal): reduce transcription by 75–80%; some normal β-globin produced\n3. Chain terminator mutations (most common cause of β⁰-thal): new stop codons within exons (nonsense mutations) OR frameshift mutations from small insertions/deletions → no functional β-globin"]','A','β⁰ = chain terminator (stop codon/frameshift) → NO β-globin. β⁺ = promoter/splicing → REDUCED β-globin. Most patients are compound heterozygotes (β⁺/β⁰) rather than true homozygotes.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thalassaemia','medium','flashcard','What are target cells and why do they appear in thalassaemia?','["Target cells (codocytes) are RBCs with a bullseye appearance on blood film — haemoglobin collects centrally and at the periphery with a pale ring in between. They result from an increased ratio of RBC membrane surface area to cell volume, which occurs in thalassaemia due to haemoglobin deficiency (underfilled cells) and membrane remodelling. Also seen in sickle cell disease, liver disease, iron deficiency, and after splenectomy."]','A','Target cells = too much membrane relative to Hb content → excess membrane folds inward creating bullseye. Seen in HbC disease (very prominent), thalassaemia, sickle cell disease, liver disease.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','easy','flashcard','What is the key cytogenetic abnormality in CML and what does it encode?','["The Philadelphia chromosome (Ph chromosome) — a shortened chromosome 22 — results from a reciprocal translocation t(9;22)(q34;q11). The ABL proto-oncogene on chromosome 9 is translocated to the BCR gene on chromosome 22, creating the BCR-ABL fusion gene. BCR-ABL encodes a constitutively active tyrosine kinase (p210 in CML) that drives growth factor-independent proliferation and survival of myeloid progenitors while preserving normal differentiation. Present in >99% of CML cases."]','A','Ph chromosome = t(9;22) = BCR-ABL. The BCR-ABL tyrosine kinase is the target of imatinib (Gleevec), the first tyrosine kinase inhibitor in clinical use — a landmark in targeted cancer therapy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','flashcard','Compare the morphology and typical age of presentation of ALL vs AML.','["ALL (Acute Lymphoblastic Leukaemia/Lymphoma):\n• Most common cancer of children; B-ALL peaks at ~3–4 years; T-ALL in adolescence\n• Lymphoblasts: small to medium, scant cytoplasm, condensed chromatin, inconspicuous nucleoli; NO Auer rods; myeloperoxidase-NEGATIVE; TdT-positive\n\nAML (Acute Myeloid Leukaemia):\n• Predominantly adults; incidence rises after age 60\n• Myeloblasts: larger, more cytoplasm, fine chromatin, prominent nucleoli; AUER RODS (pathognomonic — needle-like azurophilic cytoplasmic inclusions); myeloperoxidase-POSITIVE; TdT-negative"]','A','Auer rods = pathognomonic of AML (crystallised lysosomal granules fused into needles). TdT positivity = lymphoblast. Myeloperoxidase positivity = myeloblast. These stains are essential for lineage assignment.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','hard','flashcard','What is the significance of t(15;17) in AML and how does this inform treatment?','["t(15;17)(q22;q11-12) creates a PML-RARα fusion gene, defining Acute Promyelocytic Leukaemia (APL, FAB M3). PML-RARα encodes a chimeric protein that blocks terminal granulocytic differentiation by interfering with retinoic acid signalling. Morphologically: hypergranular promyelocytes with numerous Auer rods, often in bundles (''faggot cells''); high incidence of DIC (granules activate coagulation). Treatment: all-trans retinoic acid (ATRA) overcomes the differentiation block → induction of terminal differentiation of leukaemic cells (''differentiation therapy''). Arsenic trioxide (ATO) is also used. Together, ATRA + ATO achieves cure in >90% of APL."]','A','APL t(15;17) = PML-RARα = differentiation block + DIC. ATRA + ATO is transformative therapy — APL went from worst to best AML prognosis. Always suspect APL if bleeding + hypergranular blasts.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','flashcard','What is the significance of t(8;21) in AML?','["t(8;21)(q22;q22) creates the RUNX1-ETO (AML1-ETO) fusion gene. RUNX1 (also called AML1) and CBFB encode the core binding factor (CBF) transcription factor complex required for normal haematopoiesis. The RUNX1-ETO fusion protein blocks myeloid differentiation. Morphology: full range of myelocytic maturation present; Auer rods easily found; abnormal salmon-pink cytoplasmic granules. Prognosis: FAVOURABLE — one of the best-prognosis AML subtypes. t(8;21) and inv(16) together are called CBF-AMLs and have good response to high-dose cytarabine."]','A','CBF-AMLs [t(8;21) and inv(16)] = favourable prognosis AML. Contrast with complex karyotype or t(9;22) in AML = poor prognosis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','flashcard','Compare CLL and ALL in terms of cell of origin, immunophenotype, age, and clinical course.','["CLL (Chronic Lymphocytic Leukaemia):\n• Most common leukaemia in adults in the West; median age ~65 years\n• Mature B cells: small, round lymphocytes with coarse chromatin (''smudge cells'' on blood film)\n• Immunophenotype: CD5+, CD19+, CD20+(dim), CD23+, surface IgM (dim)\n• Indolent course; many patients asymptomatic for years; median survival ~10 years\n\nALL (Acute Lymphoblastic Leukaemia):\n• Most common childhood cancer; B-ALL peaks at 3–4 years\n• Immature B or T lymphoblasts: TdT+, CD10+(B-ALL), CD1a+(T-ALL)\n• Aggressive; rapid progression but potentially curable (>90% childhood B-ALL)"]','A','CLL: smudge cells, CD5+CD23+, indolent, adults. ALL: lymphoblasts, TdT+, aggressive but curable in children. CD5 positivity in a B-cell tumour = CLL or mantle cell lymphoma.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','easy','flashcard','What are the typical presenting features of acute leukaemia?','["Bone marrow failure (replacement by blasts):\n1. Anaemia → fatigue, pallor, dyspnoea\n2. Neutropenia → recurrent infections (bacterial, fungal)\n3. Thrombocytopenia → petechiae, purpura, mucosal bleeding, ecchymoses\nOther features: bone pain (marrow expansion), lymphadenopathy, hepatosplenomegaly (especially ALL), CNS involvement (ALL > AML), testicular enlargement (ALL), mediastinal mass (T-ALL), gum hypertrophy (AML-monocytic, M4/M5), DIC (APL, M3)."]','A','The triad of anaemia + infection + bleeding in a patient with blasts on blood film = acute leukaemia until proven otherwise. ALL presents with bone pain, CNS signs; AML presents with gum hypertrophy or DIC.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','hard','flashcard','What cytogenetic findings carry poor prognosis in ALL?','["Poor prognosis in ALL:\n• t(9;22) = BCR-ABL (Philadelphia-positive ALL) — occurs in 25% of adult B-ALL; worse prognosis than Ph-positive CML; treated with BCR-ABL inhibitors + chemotherapy\n• t(4;11) = MLL-AF4 rearrangement — infant ALL; very poor prognosis\n• Hypodiploidy (<46 chromosomes)\n\nGood prognosis in ALL:\n• Hyperdiploidy (>50 chromosomes) — common in childhood B-ALL; excellent prognosis\n• t(12;21) = ETV6-RUNX1 fusion — most common translocation in childhood B-ALL; excellent prognosis"]','A','Ph-positive ALL (t9;22) is the highest-risk adult ALL — requires tyrosine kinase inhibitors. Hyperdiploidy + age 2–10 years = best prognosis ALL. Age, WBC at diagnosis, and cytogenetics all determine ALL prognosis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','flashcard','Describe the clinical and laboratory features of CML.','["CML typically presents in middle age with insidious onset. Features: massive splenomegaly (often the most prominent finding), weight loss, fatigue, night sweats. Lab: very high WBC (often 50,000–200,000/µL) with the full spectrum of maturing granulocytes, eosinophilia and basophilia (characteristic), mild anaemia, thrombocytosis, low leukocyte alkaline phosphatase (LAP) score (distinguishes from leukaemoid reaction where LAP is high). Bone marrow: markedly hypercellular with granulocytic dominance; small dysplastic megakaryocytes. Ph chromosome/BCR-ABL on cytogenetics/PCR."]','A','CML: massive splenomegaly + very high WBC + basophilia + low LAP score + Ph chromosome. Imatinib produces haematological remission in >90% and cytogenetic remission in ~80% of chronic-phase CML.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','hard','flashcard','What are myelodysplastic syndromes (MDS) and what is their relationship to AML?','["MDS are clonal stem cell disorders characterised by ineffective haematopoiesis with dysplastic morphology (cytopenias despite normal or hypercellular marrow), risk of transformation to AML. Key features: pancytopenia; dysplastic features in ≥1 cell lines; ringed sideroblasts (Prussian blue stain showing iron-laden mitochondria in ring around nucleus); pseudo-Pelger-Hüet cells (bilobed neutrophils); hypogranular neutrophils. Causes: de novo (idiopathic, elderly) or therapy-related (after chemotherapy/radiation). 10–40% transform to AML; most die from cytopenias (infection, bleeding) before transformation."]','A','MDS = pre-leukaemic dysplasia. ''Refractory anaemia'' that doesn''t respond to B12/folate/iron. Ringed sideroblasts = iron trapped in mitochondria forming a blue ring around the nucleus.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Leukaemias','medium','flashcard','What is the three-phase progression of CML and how does each phase differ?','["1. Chronic phase (years): well-differentiated granulocytes dominate; <10% blasts in marrow; responds well to TKI therapy; most patients present here\n2. Accelerated phase: increasing blasts (10–19%), worsening cytopenia, new cytogenetic abnormalities, resistance to therapy\n3. Blast crisis (blast phase): ≥20% blasts in marrow/blood → clinically resembles acute leukaemia; blasts can be myeloid (~70%) or lymphoid (~30%); rapidly fatal without aggressive therapy. This transformation is driven by acquisition of additional mutations (loss of p53, RB, etc.)"]','A','CML progression: Chronic → Accelerated → Blast crisis. TKIs (imatinib, dasatinib, nilotinib) prevent blast crisis if started in chronic phase. Lymphoid blast crisis can respond to ALL therapy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','easy','flashcard','What is the Reed-Sternberg cell and what is its immunophenotype?','["The Reed-Sternberg (RS) cell is the malignant cell of classical Hodgkin lymphoma (HL). Morphology: large cell (45 µm diameter), binucleated or bilobed with large, inclusion-like ''owl-eye'' nucleoli (~5–7 µm, size of a small lymphocyte), abundant cytoplasm. Derived from germinal centre or post-germinal centre B cells (Ig genes rearranged and somatically hypermutated), but RS cells have lost B-cell gene expression.\nImmunophenotype of classical HL: CD15+, CD30+, PAX5+(weak), CD45−, CD20−. Diagnostic RS cells are necessary but not sufficient — must be seen in appropriate inflammatory background."]','A','OWL EYES = Reed-Sternberg cell: two large nuclei with prominent eosinophilic nucleoli. CD15+CD30+ but CD45−. Only PAX5 remains of B-cell markers (weak). Must see these in correct cellular background.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','flashcard','What are the five subtypes of Hodgkin lymphoma and which is most common?','["Classical HL (share CD15+, CD30+, CD45− immunophenotype):\n1. Nodular sclerosis (65–70%): MOST COMMON; lacunar RS cell variants + collagen bands dividing lymph node into nodules; favours mediastinum and lower cervical/supraclavicular nodes; equal sex; uncommonly EBV+\n2. Mixed cellularity (20–25%): diagnostic RS cells abundant; EBV+ in ~70%; polymorphous background; more often EBV-related; older male patients\n3. Lymphocyte-rich: rare; abundant lymphocytes; few RS cells\n4. Lymphocyte depletion: rarest; many RS cells, few lymphocytes; worst prognosis; EBV often+\n5. Lymphocyte predominance: different — RS variants called ''popcorn'' (L&H) cells; CD20+, CD15−, CD30−; indolent; rarely transforms to DLBCL"]','A','Nodular sclerosis = most common HL worldwide; favours young women; mediastinum; lacunar cells. Lymphocyte predominance is a biologically distinct disease with different immunophenotype.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','flashcard','What is diffuse large B-cell lymphoma (DLBCL) and what are its key features?','["DLBCL is the most common NHL (~25% of all adult lymphomas). It is an aggressive B-cell lymphoma composed of large neoplastic B cells (2–3× size of normal lymphocytes) that diffusely efface lymph node architecture. Most arise de novo; some from transformation of lower-grade lymphomas (follicular, CLL). Immunophenotype: CD19+, CD20+, surface Ig+, CD10±, BCL6±, MUM1±. Two major molecular subtypes by gene expression: 1. Germinal Centre B-cell type (GCB) — better prognosis; 2. Activated B-cell type (ABC) — worse prognosis. Treatment: R-CHOP (rituximab + cyclophosphamide, doxorubicin, vincristine, prednisolone) → ~60% long-term remission."]','A','DLBCL is the most common aggressive lymphoma. Treatment with R-CHOP (anti-CD20 + CHOP chemotherapy) can cure ~60%. GCB subtype has better outcomes than ABC subtype.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','flashcard','What is follicular lymphoma and what chromosomal abnormality defines it?','["Follicular lymphoma is the most common indolent NHL (20–25% of all NHL in the West). It arises from germinal centre B cells and shows a characteristic follicular (nodular) growth pattern in lymph nodes. KEY translocation: t(14;18)(q32;q21) — juxtaposes BCL2 gene (chromosome 18) to the IgH locus (chromosome 14) → BCL2 overexpression → inhibits apoptosis of germinal centre B cells (normally undergo apoptosis if antigen-unselected). Immunophenotype: CD19+, CD20+, CD10+, BCL2+, BCL6+. Clinical: waxing and waning painless lymphadenopathy; bone marrow often involved (paratrabecular pattern); median survival ~10 years; not curable with chemotherapy alone; ~30–50% transform to DLBCL over time."]','A','t(14;18) = BCL2 overexpression = anti-apoptosis in germinal centre B cells. Follicular lymphoma: indolent but incurable (in advanced stage); transforms to DLBCL (''histological transformation'') in ~40% over 10 years.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','hard','flashcard','What is Burkitt lymphoma and what is its relationship with EBV and c-MYC?','["Burkitt lymphoma is an extremely aggressive B-cell NHL defined by translocation of c-MYC (chromosome 8) to an Ig locus: most commonly t(8;14) (IgH), or t(2;8) (Igκ) or t(8;22) (Igλ). MYC overexpression drives aerobic glycolysis (Warburg effect) and rapid proliferation (shortest doubling time of any human tumour ~24 hours). Three forms: 1. African (endemic): jaw/facial bones; EBV+ in ~100%; 2. Sporadic (non-endemic): abdominal (ileocaecal) masses; EBV+ in ~20%; 3. Immunodeficiency-associated (HIV): EBV+ variable. Morphology: intermediate-sized cells, ''starry sky'' pattern (tingible-body macrophages = pale stars in dark blue sea of tumour cells), high mitotic index."]','A','Burkitt = c-MYC translocation + starry sky pattern + fastest growing human tumour. EBV drives endemic African Burkitt; sporadic has other mutations. t(8;14) is the classic translocation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','easy','flashcard','How is Hodgkin lymphoma typically staged and what is the clinical presentation?','["HL typically presents as painless, progressive lymphadenopathy — most commonly cervical nodes, then mediastinal (especially nodular sclerosis). Ann Arbor staging:\n• Stage I: single lymph node region\n• Stage II: ≥2 regions on same side of diaphragm\n• Stage III: regions on both sides of diaphragm\n• Stage IV: diffuse extranodal involvement (liver, bone marrow, etc.)\nB symptoms (fever >38°C, drenching night sweats, >10% weight loss in 6 months) worsen prognosis. Mediastinal mass can cause superior vena cava syndrome, dysphagia, or cough."]','A','HL spreads contiguously through adjacent lymph node groups (unlike NHL which is non-contiguous). B symptoms indicate worse prognosis. Pruritus and alcohol-induced pain in nodes are classic but non-specific HL symptoms.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','flashcard','What is CLL/SLL and what are smudge cells?','["CLL (Chronic Lymphocytic Leukaemia) and SLL (Small Lymphocytic Lymphoma) are the same disease differing only in distribution: CLL = predominant leukaemic phase; SLL = predominantly lymph node involvement. Both consist of small, mature-appearing B lymphocytes with coarse ''soccer ball'' chromatin. SMUDGE CELLS (basket cells): characteristic blood film finding — fragile CLL lymphocytes that are crushed during smear preparation, leaving streaked, smudged nuclear remnants. Immunophenotype: CD19+, CD20+(dim), CD5+, CD23+, surface Ig (dim). CLL is the most common leukaemia in Western adults."]','A','Smudge cells = crushed CLL lymphocytes on blood film — pathognomonic. CD5+CD23+ = CLL (vs mantle cell lymphoma which is CD5+ but CD23−). CLL is indolent but leads to hypogammaglobulinaemia → recurrent infections.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','hard','flashcard','What is the role of EBV in lymphomagenesis and which lymphomas are EBV-associated?','["EBV infects B cells via CD21 (EBV receptor). Latent EBV proteins drive B cell proliferation:\n• LMP-1 (Latent Membrane Protein-1): mimics CD40 signalling → activates NF-κB → promotes survival and proliferation; resembles Reed-Sternberg cell in structure\n• EBNA-2: transactivates c-MYC and cyclin D\nEBV-associated lymphomas: Hodgkin lymphoma (EBV+ in 30–40% classical HL; ~70% mixed cellularity); Burkitt lymphoma (100% endemic, ~20% sporadic); Primary CNS lymphoma in HIV; Post-transplant lymphoproliferative disorders (PTLD); NK/T-cell lymphoma (nasal type)"]','A','EBV = oncovirus for lymphoid cells. LMP-1 is the key oncogenic protein that activates NF-κB (survival signal). Immunocompromised patients cannot control EBV-driven B cell proliferation → lymphoma.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','medium','flashcard','What distinguishes mantle cell lymphoma from CLL/SLL immunophenotypically?','["Both mantle cell lymphoma (MCL) and CLL/SLL are CD5+ B-cell tumours with small-to-medium lymphocytes, making them easy to confuse. Key distinguishing features:\nMCL: CD5+, CD20+(bright), CD23−, cyclin D1+(due to t(11;14) overexpressing CCND1), IgH unmutated → aggressive, median survival 3–4 years, no cure with conventional chemo.\nCLL/SLL: CD5+, CD20+(dim), CD23+, cyclin D1−, ZAP70/CD38 variable → indolent, median survival ~10 years."]','A','CD23 positivity distinguishes CLL (CD23+) from mantle cell lymphoma (CD23−). Cyclin D1/CCND1 overexpression from t(11;14) is pathognomonic of MCL. MCL has much worse prognosis than CLL despite similar appearance.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Lymphomas','easy','flashcard','What are the general differences between Hodgkin lymphoma and non-Hodgkin lymphoma?','["Hodgkin Lymphoma (HL):\n• Contains Reed-Sternberg cells in reactive inflammatory background\n• Usually nodal with contiguous spread\n• Bimodal age distribution (young adults + elderly)\n• Mediastinal involvement common (nodular sclerosis)\n• Usually curable (>80% long-term survival with treatment)\n• 5 subtypes\n\nNon-Hodgkin Lymphoma (NHL):\n• No RS cells; tumour cells are the lymphoma cells\n• Often non-contiguous, extranodal spread is common\n• Predominantly middle-aged to elderly\n• Very heterogeneous — 30+ subtypes\n• Prognosis varies widely (indolent to highly aggressive)\n• More common overall than HL"]','A','HL: RS cells, contiguous spread, curable. NHL: no RS cells, non-contiguous, heterogeneous prognosis. The presence or absence of RS cells in a lymph node biopsy is the defining distinction.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','flashcard','What is the CRAB criteria for multiple myeloma?','["CRAB criteria define end-organ damage requiring treatment in multiple myeloma:\nC — hyperCalcaemia (serum calcium >11 mg/dL; from osteoclast activation by RANKL from myeloma cells)\nR — Renal failure (creatinine >2 mg/dL; from Bence Jones protein tubular injury, hypercalcaemia, amyloid)\nA — Anaemia (Hb <10 g/dL; from marrow replacement, renal failure reducing EPO, cytokine suppression)\nB — Bone disease (lytic lesions, osteoporosis, pathological fractures; no osteoblastic repair as RUNX2/osterix inhibited)"]','A','CRAB = Calcium↑, Renal failure, Anaemia, Bone lesions. Any one CRAB criterion + clonal plasma cells ≥10% = symptomatic myeloma requiring treatment. Lytic lesions have no sclerotic rim because osteoblasts are suppressed.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','flashcard','What is the M protein (paraprotein) and how is it detected?','["M protein (monoclonal/M component) is a monoclonal immunoglobulin (or fragment) produced by the neoplastic plasma cell clone. It is detected by: 1. Serum protein electrophoresis (SPEP): a sharp, narrow spike (M-spike) in the gamma region; 2. Immunofixation electrophoresis: identifies the heavy and light chain class; 3. Serum free light chain assay: detects excess free kappa or lambda chains. In myeloma, excess free light chains (Bence Jones proteins) are excreted in urine (small, filtered by glomerulus → detected by urine protein electrophoresis or immunofixation — NOT by routine dipstick). Most common M protein in myeloma: IgG (~55%), then IgA (~25%), then light chain only (~20%)."]','A','M-spike on SPEP = monoclonal protein = suspect plasma cell dyscrasia. Bence Jones = free light chains in urine — cause tubular damage (cast nephropathy). Dipstick detects albumin, NOT Bence Jones proteins.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','flashcard','Describe the bone marrow findings in multiple myeloma.','["Bone marrow shows increased plasma cells, usually >30% of cellularity (diagnostic threshold ≥10% clonal plasma cells). Plasma cells may have ''clock-face'' (cartwheel) chromatin distribution, perinuclear hof (clear Golgi zone), eccentric nucleus. Variants: plasmablastic (immature, aggressive), multinucleated forms. Plasma cells infiltrate diffusely or in nodules. Immunohistochemistry: CD138+ (syndecan-1), CD38+, CD56+(abnormal), monotypic light chain (kappa or lambda) confirming clonality. Rouleaux formation in peripheral blood (red cells stacked like coins from high M protein)."]','A','Plasma cells: clock-face chromatin + perinuclear hof + eccentric nucleus. CD138 (syndecan-1) is the key marker of plasma cells. Rouleaux on blood film + elevated ESR = high protein levels — suspect myeloma.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','hard','flashcard','How do myeloma cells cause bone destruction and why are the lesions lytic (not sclerotic)?','["Myeloma cells produce RANKL (receptor activator of NF-κB ligand) and DKK1 (Dickkopf-1). RANKL activates osteoclast precursors → increased osteoclastic bone resorption → lytic lesions, hypercalcaemia. DKK1 inhibits the Wnt signalling pathway in osteoblasts → suppression of osteoblast activity → NO new bone formation → lytic lesions WITHOUT sclerotic rim. This is why myeloma bone lesions are NOT detected by bone scan (which relies on osteoblastic activity) — plain radiographs or CT/PET are used instead (''lytic punched-out lesions'' especially in skull, vertebrae, ribs, long bones)."]','A','Myeloma = osteoclast UP + osteoblast DOWN = pure lytic lesions. Bone scan negative in myeloma (no osteoblastic repair). Use skeletal survey or CT instead. Bisphosphonates inhibit osteoclasts and are standard supportive therapy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','flashcard','What is the relationship between multiple myeloma and amyloidosis?','["In myeloma, excess immunoglobulin light chains (particularly lambda chains) can aggregate and form amyloid fibrils of the AL (amyloid light chain) type — the most common form of systemic amyloidosis. AL amyloid deposits in multiple organs: kidneys (nephrotic syndrome), heart (restrictive cardiomyopathy, low-voltage ECG), peripheral nerves (sensorimotor neuropathy), liver (hepatomegaly), soft tissues (macroglossia, carpal tunnel syndrome, ''shoulder pad sign''). Unlike cast nephropathy (Bence Jones), amyloid causes glomerular deposition → proteinuria including albumin → detectable by dipstick."]','A','AL amyloid = light chains misfolded into fibrils. Macroglossia is a classic but rare clinical sign. Cardiac amyloid = restrictive cardiomyopathy + low voltage on ECG (paradox of thickened wall + low voltage).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','flashcard','What is MGUS and how does it relate to multiple myeloma?','["MGUS (Monoclonal Gammopathy of Undetermined Significance) is defined by: M protein <3 g/dL, bone marrow plasma cells <10%, and NO CRAB criteria. It is present in ~3% of adults >50 years and ~5% >70 years. Risk of progression to myeloma or related disorder: ~1% per year. Requires monitoring but no treatment. Smoldering myeloma: M protein ≥3 g/dL and/or marrow plasma cells 10–59% but NO CRAB criteria → higher risk (~10% per year progression). Both are pre-malignant states on the spectrum: MGUS → Smoldering myeloma → Symptomatic myeloma."]','A','MGUS → Smoldering myeloma → Symptomatic myeloma: a spectrum requiring treatment only at the symptomatic stage. MGUS requires annual monitoring for CRAB criteria. Risk factors for progression: M protein level, IgA/IgM type, abnormal free light chain ratio.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','hard','flashcard','What is Waldenström macroglobulinaemia?','["Waldenström macroglobulinaemia (WM) is a low-grade B-cell lymphoma (lymphoplasmacytic lymphoma) producing a monoclonal IgM paraprotein. Because most IgM is intravascular (high molecular weight pentamer), high levels cause hyperviscosity syndrome: blurred vision (dilated, tortuous retinal veins → ''sausage link'' veins on fundoscopy), headaches, confusion, stroke, bleeding. Other features: anaemia (marrow infiltration), lymphadenopathy, hepatosplenomegaly, Raynaud''s phenomenon, cold agglutinin haemolytic anaemia. Highly associated with MYD88 L265P mutation (~90%). Treatment: plasmapheresis for acute hyperviscosity; rituximab-based chemotherapy."]','A','WM = lymphoplasmacytic lymphoma + IgM = hyperviscosity. Sausage-link retinal veins = pathognomonic fundoscopic sign of hyperviscosity. MYD88 mutation distinguishes WM from myeloma and other lymphomas.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','medium','flashcard','What is cast nephropathy (myeloma kidney) and how does it differ from AL amyloid nephropathy?','["Cast nephropathy: free light chains (Bence Jones proteins) filtered by glomeruli precipitate in distal tubules/collecting ducts, forming large casts that obstruct tubular flow and trigger a giant cell inflammatory reaction. Leads to acute or chronic renal failure. Protein on dipstick = NEGATIVE (Bence Jones not detected by albumin-specific dipstick); confirmed by urine immunofixation.\n\nAL amyloid nephropathy: amyloid fibrils deposit in glomerular mesangium → nephrotic syndrome (albuminuria). Protein on dipstick = POSITIVE (albumin loss).\n\nKey distinction: cast nephropathy = tubular; amyloid = glomerular."]','A','Myeloma kidney = cast nephropathy (Bence Jones casts in tubules) vs amyloid kidney (glomerular deposits). Dipstick positive = albumin = amyloid. Dipstick negative with protein on UPEP = cast nephropathy/Bence Jones.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','hard','flashcard','What cytokines drive myeloma cell growth and survival, and what are their therapeutic implications?','["IL-6 is the most important myeloma growth and survival factor; produced by stromal cells in the bone marrow microenvironment. IL-6 activates JAK-STAT3 and MAPK pathways → proliferation and anti-apoptosis. Other growth factors: APRIL, BAFF (B-cell survival factors), VEGF (angiogenesis). Myeloma cells are prone to accumulating misfolded proteins due to massive Ig secretion → highly dependent on the proteasome for protein quality control. This vulnerability is exploited by PROTEASOME INHIBITORS (bortezomib, carfilzomib) which cause ER stress and apoptosis in myeloma cells. Thalidomide-like drugs (IMiDs: lenalidomide, pomalidomide) impair the bone marrow microenvironment and have direct anti-myeloma and anti-angiogenic effects."]','A','IL-6 = key myeloma growth factor from stroma. Myeloma treatment pillars: proteasome inhibitors (bortezomib) + IMiDs (lenalidomide) + steroids (dexamethasone) + anti-CD38 antibody (daratumumab) + autologous stem cell transplant.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myeloma','easy','flashcard','What is a solitary plasmacytoma and how does it differ from multiple myeloma?','["Solitary plasmacytoma is a localised tumour of neoplastic plasma cells occurring as a SINGLE mass either in bone (most common: vertebra, pelvis, skull, long bones) or in soft tissue (extramedullary — usually upper aerodigestive tract). Bone marrow biopsy OUTSIDE the lesion is normal (<10% plasma cells). No CRAB criteria. Small or absent M protein. May be cured by local radiotherapy. Extramedullary plasmacytoma rarely progresses to systemic disease. Osseous (bone) solitary plasmacytoma progresses to myeloma in ~50% within 10 years — requires long-term monitoring."]','A','Solitary plasmacytoma = single lesion, normal bone marrow elsewhere, no CRAB. Can be cured by radiotherapy. ~50% of osseous plasmacytomas eventually progress to myeloma.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','easy','flashcard','What is aplastic anaemia and what are its main causes?','["Aplastic anaemia is a disorder characterised by destruction or suppression of haematopoietic stem cells leading to a hypocellular bone marrow and pancytopenia (anaemia + neutropenia + thrombocytopenia). Causes:\n• Idiopathic (~65%): most common — suspected immune-mediated (autoreactive T cells producing IFN-γ and TNF → HSC destruction)\n• Drugs/toxins: chloramphenicol, benzene, NSAIDs, gold\n• Infections: viral hepatitis (non-A, non-B, non-C), EBV, CMV, parvovirus B19\n• Inherited: Fanconi anaemia (DNA repair defect), dyskeratosis congenita (telomerase mutation)\n• Radiation\nStrongly associated with PNH (paroxysmal nocturnal haemoglobinuria)"]','A','Aplastic anaemia = hypocellular marrow + pancytopenia. Idiopathic/autoimmune is most common. Treatment: immunosuppression (anti-thymocyte globulin + cyclosporin) or allogeneic stem cell transplant.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','flashcard','How does the bone marrow appearance differ between aplastic anaemia and myelodysplastic syndrome?','["Aplastic anaemia: markedly HYPOCELLULAR marrow (<25% cellularity); the marrow space is replaced by fat cells and fibrous stroma; few residual haematopoietic cells; no dysplastic features. Biopsy (trephine) is essential — aspirate may yield only fat and sparse cells (''dry tap'').\n\nMDS: bone marrow is usually NORMOCELLULAR or HYPERCELLULAR despite peripheral blood cytopenias (hallmark of ineffective haematopoiesis); dysplastic features in ≥1 cell lineages; ringed sideroblasts, pseudo-Pelger-Hüet cells, hypogranular neutrophils, large hypolobated megakaryocytes.\n\nKey distinction: aplastic = empty marrow; MDS = full but dysfunctional marrow."]','A','Aplastic anaemia = empty marrow (fat + stroma). MDS = full marrow but cells can''t mature properly. Both cause cytopenias but by opposite mechanisms (no production vs ineffective production).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','flashcard','What are ringed sideroblasts and what is their significance?','["Ringed sideroblasts are abnormal erythroid precursors in the bone marrow in which iron-laden mitochondria form a ring around ≥1/3 of the nucleus, detected by Prussian blue stain. Iron accumulates in mitochondria due to defects in haem synthesis or mitochondrial iron processing. Significance: >15% ringed sideroblasts define MDS with ring sideroblasts (MDS-RS); often associated with SF3B1 mutation (splicing factor). Also seen in: congenital sideroblastic anaemia (X-linked, δ-ALA synthase mutation), alcohol excess, lead poisoning, pyridoxine (B6) deficiency, isoniazid treatment."]','A','Ringed sideroblasts = iron stuck in mitochondria forming blue ring on Prussian blue stain. SF3B1 mutation is the most common mutation in MDS-RS and predicts better prognosis within MDS. Not the same as haemosiderin-laden macrophages.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','hard','flashcard','Describe the dysplastic morphological features seen in MDS across each cell lineage.','["Erythroid dysplasia: multinucleation, nuclear budding, karyorrhexis, megaloblastoid change, cytoplasmic vacuolation, ringed sideroblasts.\n\nMyeloid (granulocyte) dysplasia: hypogranular neutrophils (loss of cytoplasmic granules), pseudo-Pelger-Hüet cells (bilobed or non-segmented neutrophils mimicking Pelger-Hüet anomaly), hypersegmented neutrophils, abnormal nuclear chromatin.\n\nMegakaryocyte dysplasia: micromegakaryocytes (small, mononuclear or bilobed), widely separated nuclear lobes, large mononuclear megakaryocytes.\n\nDiagnostic threshold: ≥10% dysplastic cells in any lineage."]','A','Pseudo-Pelger-Hüet cells = bilobed neutrophils that LOOK like Pelger-Hüet anomaly (inherited) but are acquired in MDS. Hypogranular neutrophils are functionally impaired → increased infection risk.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','flashcard','What is the pathogenesis of immune-mediated aplastic anaemia?','["The dominant model involves autoreactive CD8+ and CD4+ T cells that target and destroy haematopoietic stem cells (HSCs). Proposed sequence: 1. An environmental insult (drug, virus, unknown) antigenically alters HSC surface proteins; 2. Autoreactive T cells are activated and produce IFN-γ and TNF; 3. These cytokines suppress and kill HSC progenitors via apoptosis (Fas-FasL pathway); 4. The few surviving HSCs are exhausted. Evidence: T-cell depletion with anti-thymocyte globulin (ATG) + cyclosporin produces haematological responses in ~70% of patients. Additionally, telomerase mutations (TERT, TERC, DKC1) are found in ~25% of aplastic anaemia patients → accelerated telomere shortening → premature HSC exhaustion."]','A','Aplastic anaemia pathogenesis: autoreactive T cells (IFN-γ, TNF) kill HSCs. Treatment: ATG + cyclosporin (immunosuppression) or allogeneic transplant (curative). Telomere defects = second major mechanism.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','easy','flashcard','What is the clinical presentation of MDS and what causes the cytopenias?','["MDS predominantly affects elderly patients (median age ~70). Presenting features reflect cytopenias: anaemia (most common: fatigue, pallor, dyspnoea — often macrocytic but can be normocytic or microcytic), infections (neutropenia), bleeding/bruising (thrombocytopenia). Many are asymptomatic and diagnosed incidentally on routine blood count. MDS cytopenias result from INEFFECTIVE HAEMATOPOIESIS — the marrow produces abnormal cells that undergo intramedullary apoptosis before reaching the blood, and the few cells released are dysfunctional. This paradox (cells in marrow but not in blood) defines MDS."]','A','MDS = cytopenias despite normal/hypercellular marrow = ineffective haematopoiesis. Average age at diagnosis: 70 years. Think MDS in elderly patients with unexplained macrocytic or refractory anaemia that does not respond to B12/folate/iron.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','hard','flashcard','What chromosomal abnormalities are common in MDS and what is the significance of del(5q)?','["Common cytogenetic abnormalities in MDS: del(5q), del(7q)/monosomy 7, del(20q), trisomy 8, complex karyotype (≥3 abnormalities = worst prognosis). Del(5q) — isolated deletion of the long arm of chromosome 5 — has a distinctive syndrome: refractory macrocytic anaemia, normal or elevated platelet count, hypolobated megakaryocytes, <5% blasts, female predominance, relatively good prognosis. Importantly, isolated 5q− is specifically responsive to lenalidomide (thalidomide-like drug), producing red cell transfusion independence in ~70% and cytogenetic remission. Loss of RPS14 (ribosomal protein gene on 5q) is thought to cause the erythroid failure."]','A','del(5q) syndrome = macrocytic anaemia + high/normal platelets + hypolobated megakaryocytes + lenalidomide responsive. Monosomy 7 = worst prognosis in MDS. Complex karyotype also = poor prognosis.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','flashcard','How does therapy-related MDS (t-MDS) differ from de novo MDS?','["Therapy-related MDS (t-MDS) arises following prior cytotoxic therapy (chemotherapy and/or radiotherapy) for another malignancy. Two main types by prior treatment: 1. Alkylating agent/radiation-related t-MDS: latency 5–7 years; loss of chromosomes 5 and/or 7 (del5q, del7q, monosomy 7) common; tri- or quadrilineage dysplasia; high risk of AML transformation. 2. Topoisomerase II inhibitor-related: latency 1–3 years; presents directly as AML with balanced translocations (e.g., 11q23 MLL rearrangements). t-MDS has a much worse prognosis than de novo MDS: median survival 4–8 months; rapid AML transformation; cytopenias more severe; poor response to treatment."]','A','t-MDS = prior chemo/radiotherapy → latency 5–7 years (alkylators) → del(5q)/del(7q). Much worse prognosis than de novo MDS. Think t-MDS in cancer survivors presenting with new cytopenias years after treatment.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','hard','flashcard','What is the differential diagnosis of pancytopenia and how do you approach it?','["Pancytopenia = simultaneous reduction in RBCs, WBCs, and platelets. Approach: examine blood film + bone marrow aspirate/trephine biopsy.\n\nHypocellular marrow: aplastic anaemia (primary), marrow replacement by tumour/fibrosis, radiation-induced\n\nNormocellular or hypercellular marrow with ineffective haematopoiesis: MDS, megaloblastic anaemia (B12/folate deficiency), SLE, alcohol, hypersplenism (peripheral destruction)\n\nMarrow infiltration (leukoerythroblastic picture — nucleated RBCs + immature WBCs): acute leukaemia, lymphoma, myeloma, myelofibrosis, metastatic carcinoma\n\nPeripheral destruction: hypersplenism (congestive splenomegaly), Evans syndrome (autoimmune haemolytic anaemia + ITP)"]','A','Pancytopenia + hypocellular marrow = aplastic anaemia. Pancytopenia + hypercellular marrow = ineffective haematopoiesis (MDS, megaloblastic). Bone marrow biopsy is essential to differentiate these.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Myelodysplastic Syndrome & Aplastic Anaemia','medium','flashcard','What is leukoerythroblastosis and what conditions cause it?','["Leukoerythroblastosis is the appearance of immature myeloid cells (myelocytes, metamyelocytes) AND nucleated red blood cells (normoblasts) in the peripheral blood simultaneously. It indicates severe marrow stress or displacement of normal marrow architecture. Causes: 1. Bone marrow infiltration: myelofibrosis, metastatic carcinoma, lymphoma, multiple myeloma, Gaucher''s disease; 2. Severe haemolytic anaemia or haemorrhage; 3. Response to extreme marrow stress. The combination of nucleated RBCs + ''left-shifted'' granulocytes on blood film should always prompt bone marrow biopsy."]','A','Leukoerythroblastosis = immature WBCs + nucleated RBCs in peripheral blood = marrow infiltration until proven otherwise. ''Tear-drop'' cells (dacryocytes) + leukoerythroblastic picture = classic of myelofibrosis.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','easy','flashcard','What is immune thrombocytopenic purpura (ITP) and what are the autoantibodies involved?','["ITP is a bleeding disorder caused by autoantibody-mediated destruction of platelets. Autoantibodies (predominantly IgG) target platelet membrane glycoproteins, most commonly GPIIb-IIIa (αIIbβ₃ integrin) or GPIb-IX (von Willebrand factor receptor). Opsonised platelets are recognised by IgG Fc receptors on macrophages → phagocytosed and destroyed predominantly in the spleen. Autoantibodies may also damage megakaryocytes, reducing platelet production.\nTwo forms: Chronic ITP (adults, predominantly women >30 years; primary or secondary to SLE, CLL, HIV, drugs); Acute ITP (children; self-limited; post-viral; usually resolves in 6 months)."]','A','ITP = anti-GPIIb-IIIa or anti-GPIb-IX IgG autoantibodies → splenic destruction of platelets. Spleen is both the site of autoantibody production (plasma cells) AND platelet destruction — explains why splenectomy is effective.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','flashcard','What are the clinical and lab features of ITP and how is it treated?','["Clinical: petechiae, purpura, ecchymoses, mucosal bleeding (epistaxis, gingival, menorrhagia). Usually no splenomegaly. Platelet count typically <100,000/µL; may be <20,000/µL in severe cases.\nLab: isolated thrombocytopenia; normal PT and APTT (coagulation factors intact); peripheral blood shows megathrombocytes (large platelets — sign of accelerated production); bone marrow: increased megakaryocytes (normal morphology).\nTreatment: 1st line — corticosteroids (prednisolone), IVIG (emergency); 2nd line — splenectomy; 3rd line — rituximab (anti-CD20), TPO agonists (eltrombopag, romiplostim)."]','A','ITP: thrombocytopenia + normal PT/APTT + increased megakaryocytes in marrow + large platelets. If isolated thrombocytopenia in young woman, think ITP. Megathrombocytes = reactive thrombopoiesis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','hard','flashcard','What is TTP and what is the role of ADAMTS13?','["Thrombotic Thrombocytopenic Purpura (TTP) is defined by the pentad: fever, thrombocytopenia, microangiopathic haemolytic anaemia (MAHA), transient neurological deficits, and renal failure. ADAMTS13 (''vWF metalloprotease'') is a plasma enzyme that normally cleaves ultra-large von Willebrand factor (UL-vWF) multimers into smaller, less active fragments. In TTP, ADAMTS13 is deficient (acquired: autoantibodies in >95% of cases; inherited: Upshaw-Schulman syndrome). Uncleaved UL-vWF multimers accumulate → spontaneously activate platelets → platelet microthrombi in small vessels → ischaemia (brain, kidney) + MAHA (RBCs shear through fibrin clots → schistocytes)."]','A','TTP = ADAMTS13 deficiency → UL-vWF accumulates → platelet microthrombi → FAT RN pentad: Fever, MAHA, Thrombocytopenia, Renal failure, Neurological signs. Treatment: plasma exchange (removes autoantibodies + replenishes ADAMTS13) — life-saving.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','flashcard','What are the key differences between TTP and DIC on laboratory testing?','["TTP:\n• Thrombocytopenia + MAHA (schistocytes)\n• PT and APTT: NORMAL (coagulation cascade not primarily activated)\n• Fibrinogen: NORMAL\n• D-dimers: mildly elevated or normal\n• ADAMTS13 activity: markedly reduced (<10%)\n\nDIC:\n• Thrombocytopenia + MAHA\n• PT and APTT: PROLONGED (consumption of coagulation factors)\n• Fibrinogen: LOW (consumed)\n• D-dimers: markedly ELEVATED (fibrinolysis)\n• ADAMTS13: normal\n\nBoth cause microangiopathic haemolytic anaemia and thrombocytopenia, but DIC additionally causes coagulopathy."]','A','TTP: normal PT/APTT + low ADAMTS13. DIC: prolonged PT/APTT + low fibrinogen + high D-dimers. This is a classic exam distinction: TTP does NOT consume clotting factors; DIC does.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','flashcard','Describe the pathogenesis and laboratory features of haemophilia A.','["Haemophilia A is an X-linked recessive disorder caused by deficiency of factor VIII (F8 gene mutations; inversions in intron 22 most common severe form; also point mutations, small indels). Factor VIII is an essential cofactor of factor IXa in activating factor X on platelet surfaces (intrinsic pathway). Without F8 → impaired tenase complex → deficient thrombin generation → failure of secondary haemostasis.\nLab: prolonged APTT (intrinsic pathway defective), NORMAL PT (extrinsic pathway intact), NORMAL bleeding time (platelet function intact), reduced factor VIII assay.\nClinical: haemarthroses (joints), deep muscle haematomas, post-surgical bleeding; petechiae ABSENT. Severity: mild (F8 1–5%), moderate (1–5%), severe (<1%)."]','A','Haemophilia A: F8 deficiency → prolonged APTT, normal PT. Classic triad: haemarthroses + muscle bleeds + post-surgical bleeding. NO petechiae (platelet function normal). Treat with recombinant F8 or emicizumab.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','flashcard','How does haemophilia B differ from haemophilia A?','["Haemophilia B (Christmas disease) is clinically indistinguishable from haemophilia A but is caused by deficiency of factor IX (F9 gene, X-linked recessive). Like F8, F9 is part of the intrinsic pathway (tenase complex). Lab findings: identical to haemophilia A — prolonged APTT, normal PT; differentiated only by specific factor assays. Haemophilia B is about 4× less common than haemophilia A. Named after Stephen Christmas, the first identified patient. Treatment: recombinant factor IX or factor IX concentrates. Gene therapy (etranacogene dezaparvovec) has recently shown curative potential for haemophilia B."]','A','Haemophilia A vs B: identical clinical picture, identical PT/APTT pattern — differentiated ONLY by factor assay (F8 vs F9). A is 4× more common than B. Both X-linked recessive.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','hard','flashcard','What is DIC, what triggers it, and what are its haematological consequences?','["DIC (Disseminated Intravascular Coagulation) is a secondary coagulopathy characterised by widespread intravascular activation of coagulation → consumption of platelets and clotting factors + activation of fibrinolysis, causing simultaneous thrombosis and bleeding. Triggers: 1. Release of tissue factor/procoagulants (obstetric catastrophes — abruption, amniotic fluid embolism; malignancy — APL M3, mucin-secreting adenocarcinoma; trauma, burns, snake venom); 2. Widespread endothelial injury (sepsis, endotoxin → TNF → endothelial TF expression; heat stroke; vasculitis). Consequences: microthrombi → organ ischaemia + MAHA (schistocytes); consumption → thrombocytopenia + prolonged PT/APTT + low fibrinogen + high D-dimers."]','A','DIC causes = STOP Making New Thrombi: Sepsis, Trauma, Obstetric, Pancreatitis, Malignancy, Necrosis, Transfusion. Lab: all abnormal — low platelets, low fibrinogen, high PT/APTT, high D-dimers, schistocytes.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','easy','flashcard','How do platelet disorders differ clinically from coagulation factor deficiencies?','["Platelet disorders (thrombocytopenia or platelet dysfunction):\n• Bleeding type: small vessel / mucocutaneous\n• Manifestations: petechiae (pinpoint <2mm flat), purpura, ecchymoses, gingival bleeding, epistaxis, menorrhagia, immediate post-traumatic bleeding\n• Examples: ITP, TTP, drug-induced, Bernard-Soulier, Glanzmann thrombasthenia\n\nCoagulation factor deficiencies:\n• Bleeding type: large vessel / deep tissue\n• Manifestations: haemarthroses, deep muscle haematomas, retroperitoneal bleeds, delayed post-traumatic/post-surgical bleeding, NO petechiae\n• Examples: Haemophilia A/B, vWD, DIC"]','A','Platelet defect = mucocutaneous (petechiae). Coagulation defect = deep tissue (haemarthroses). This clinical distinction guides initial investigation: platelet count + bleeding time (platelet) vs PT + APTT (coagulation).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','hard','flashcard','What is von Willebrand disease (vWD) and what are its types?','["vWD is the most common inherited bleeding disorder (~1% prevalence). VWF: 1. Acts as a carrier protein for factor VIII in plasma (protecting it from proteolysis); 2. Mediates platelet adhesion to subendothelial collagen (via GPIb-IX receptor) — essential for primary haemostasis.\nTypes:\n• Type 1 (75%): quantitative deficiency (mild–moderate); autosomal dominant; responds to desmopressin (DDAVP → releases VWF from Weibel-Palade bodies)\n• Type 2: qualitative defect (A, B, M, N subtypes); Type 2A most common — loss of high-molecular-weight multimers\n• Type 3: severe quantitative deficiency; autosomal recessive; resembles haemophilia A (low FVIII)\nLab: prolonged bleeding time + prolonged APTT (low FVIII); low VWF antigen; abnormal platelet aggregation with ristocetin."]','A','VWF = platelet adhesion (GPIb) + FVIII carrier. Type 1 vWD responds to DDAVP. Ristocetin cofactor assay measures VWF function. Lab: prolonged BT + prolonged APTT (unlike pure platelet disorder which has normal APTT).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Bleeding Disorders','medium','flashcard','What are the laboratory tests used to differentiate platelet disorders from coagulation disorders?','["Tests of PRIMARY haemostasis (platelets and vascular):\n• Platelet count (FBC)\n• Peripheral blood film (platelet size, morphology)\n• Bleeding time (BT): prolonged in platelet disorders and vWD; normal in coagulation factor deficiencies\n• Platelet aggregation studies + ristocetin cofactor assay (vWD)\n\nTests of SECONDARY haemostasis (coagulation cascade):\n• PT/INR: tests extrinsic + common pathway (factors VII, X, V, II, I); prolonged by warfarin, factor VII deficiency, liver disease\n• APTT: tests intrinsic + common pathway (factors XII, XI, IX, VIII, X, V, II, I); prolonged in haemophilia A/B, heparin, DIC\n• Fibrinogen level + D-dimers (fibrinolysis/DIC)\n• Specific factor assays (FVIII, FIX, FVII etc.)"]','A','PT tests extrinsic/common pathway. APTT tests intrinsic/common pathway. Haemophilia A/B: APTT ↑, PT normal. Warfarin: PT ↑, APTT may be mildly ↑. DIC: both ↑ + low fibrinogen + high D-dimers.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','easy','flashcard','What is factor V Leiden and why does it cause thrombophilia?','["Factor V Leiden is the most common inherited thrombophilia in Caucasians (~5% carrier frequency). A point mutation (Arg506Gln) in the factor V gene renders factor Va resistant to cleavage and inactivation by activated protein C (APC resistance). Normally, APC inactivates FVa and FVIIIa to limit coagulation. In FVL, FVa continues to amplify thrombin generation unchecked → hypercoagulable state. Heterozygotes have a 3–8-fold increased VTE risk; homozygotes have 80-fold increased risk. Autosomal dominant with variable penetrance. Particularly risky in combination with oral contraceptives, pregnancy, or surgery."]','A','Factor V Leiden = APC resistance = most common inherited thrombophilia. Test: APC resistance assay; confirmed by genetic testing (Arg506Gln mutation). Screen family members of young VTE patients.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','flashcard','What is the prothrombin G20210A mutation and what does it cause?','["The prothrombin G20210A mutation is the second most common inherited thrombophilia in Caucasians (~2–3% prevalence). A point mutation in the 3'' untranslated region of the prothrombin gene results in increased prothrombin mRNA stability → elevated plasma prothrombin (factor II) levels (~30% higher than normal). Elevated prothrombin → increased thrombin generation → prothrombotic state. Heterozygotes have a 2–3-fold increased VTE risk. Combined with factor V Leiden or OCP use, the risk is markedly amplified. Autosomal dominant; detected by PCR-based genetic testing."]','A','Prothrombin 20210A: increased prothrombin levels → increased thrombin → thrombosis. 2nd most common inherited thrombophilia. When found with FVL = synergistic risk. No specific lab test other than genetic testing.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','flashcard','What is antiphospholipid syndrome (APS) and what are its clinical manifestations?','["APS is an acquired autoimmune thrombophilia characterised by persistent antiphospholipid antibodies (aPL) causing arterial and/or venous thrombosis, and pregnancy morbidity. Three main antibodies: 1. Lupus anticoagulant (LA) — prolongs phospholipid-dependent clotting tests in vitro (paradoxically causes thrombosis in vivo); 2. Anticardiolipin antibodies (aCL — IgG or IgM); 3. Anti-β₂-glycoprotein I antibodies. Clinical manifestations: recurrent venous/arterial thrombosis (DVT, PE, stroke, MI), recurrent pregnancy loss (miscarriage, stillbirth — placental thrombosis), thrombocytopenia, livedo reticularis. Can be primary (no underlying disease) or secondary (SLE most common). Catastrophic APS = simultaneous thrombosis in multiple organs."]','A','APS: aPL antibodies + thrombosis/pregnancy loss. Lupus anticoagulant = prolonged APTT in vitro but PRO-thrombotic in vivo (paradox). Treat with long-term anticoagulation (warfarin). Hydroxychloroquine for SLE-associated APS.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','flashcard','Describe the Virchow''s triad and how each component contributes to DVT formation.','["Virchow''s triad — three factors predisposing to venous thrombosis:\n1. Stasis (abnormal blood flow): immobility (bed rest, long flights, surgery), cardiac failure, varicose veins → sluggish flow allows clotting factors to accumulate and contact activated endothelium\n2. Endothelial injury: trauma, surgery, indwelling catheters, inflammation → exposes subendothelial collagen and tissue factor → activates coagulation and platelets\n3. Hypercoagulability: inherited (FVL, prothrombin mutation, protein C/S deficiency, antithrombin deficiency) or acquired (APS, malignancy, OCP, pregnancy, nephrotic syndrome)\nMost thrombi in DVT form in the valve pockets of deep leg veins where flow is most stagnant."]','A','Virchow''s triad: Stasis + Endothelial injury + Hypercoagulability. Most DVTs form in the valve pockets of calf veins — sites of maximum stasis. All three factors often coexist in surgical patients.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','flashcard','What are the pathological consequences of pulmonary embolism?','["Clinical consequences depend on clot size and cardiopulmonary reserve:\n1. Large/massive PE (saddle embolus at pulmonary artery bifurcation): sudden death; acute right heart failure (acute cor pulmonale); haemodynamic collapse/shock\n2. Medium PE: pulmonary infarction (wedge-shaped, haemorrhagic, peripheral; affects lower lobes most often); pleuritis; haemoptysis; pleural effusion\n3. Small/multiple PE: often silent; repeated episodes → pulmonary hypertension + chronic cor pulmonale\nMorphology of infarct: classically haemorrhagic (red-brown) wedge-shaped; base at pleura, apex pointing to hilum; overlying fibrinous pleuritis. 60–80% of emboli are clinically silent."]','A','Massive PE → sudden death or acute cor pulmonale. Medium PE → pulmonary infarction (haemorrhagic wedge). Small PE → silent or chronic pulmonary hypertension. >95% of PE arise from DVT in lower leg veins.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','flashcard','What are the inherited deficiencies of natural anticoagulants and what is their thrombotic risk?','["Natural anticoagulant deficiencies (all autosomal dominant, variable penetrance):\n1. Antithrombin III (AT III) deficiency: inhibits thrombin, FXa, FIXa; deficiency → 10–50-fold VTE risk; does NOT respond to heparin (heparin works by activating AT III → give alternative anticoagulant in AT III-deficient patients with HIT)\n2. Protein C deficiency: protein C (vitamin K-dependent) inactivates FVa and FVIIIa; deficiency → 7-fold VTE risk; can cause warfarin-induced skin necrosis (protein C has shorter half-life than procoagulant factors → transient hypercoagulability at warfarin initiation)\n3. Protein S deficiency: cofactor for protein C; similar VTE risk and clinical manifestations as protein C deficiency"]','A','AT III deficiency = heparin resistance (heparin needs AT III to work). Protein C deficiency = warfarin skin necrosis risk at initiation (bridge with heparin). Protein C + S = vitamin K-dependent anticoagulants.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','easy','flashcard','What are the risk factors for venous thromboembolism (VTE)?','["Primary (inherited) risk factors:\n• Factor V Leiden (most common), prothrombin G20210A, protein C/S deficiency, antithrombin III deficiency, hyperhomocysteinaemia\n\nSecondary (acquired) risk factors:\n• Surgery (especially orthopaedic — hip/knee replacement, hip fracture)\n• Prolonged immobility (bed rest, long-haul flights)\n• Malignancy (especially mucin-secreting adenocarcinoma)\n• Oral contraceptives/HRT (oestrogen increases clotting factors)\n• Pregnancy and puerperium\n• Antiphospholipid syndrome\n• Obesity\n• Previous VTE\n• Heart failure, nephrotic syndrome"]','A','VTE risk factors: THROMBOSIS mnemonic — Trauma/surgery, HRT/OCP, Reduced mobility, Obesity, Malignancy, Blood disorders (thrombophilia), Old age, Smoking, Immobilisation, Sickness (medical illness), Stasis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','flashcard','How does antiphospholipid syndrome cause recurrent pregnancy loss?','["In APS, antiphospholipid antibodies (particularly anti-β₂GPI and anticardiolipin) bind phospholipids and phospholipid-binding proteins on trophoblast and placental endothelium. This causes: 1. Placental thrombosis: thrombi in uteroplacental vessels → placental infarction → foetal growth restriction → recurrent miscarriage or stillbirth (usually second trimester). 2. Impaired trophoblast invasion and placentation (non-thrombotic mechanisms). 3. Complement activation at the maternal-foetal interface contributes to placental damage. Treatment in pregnancy: low-dose aspirin + low-molecular-weight heparin (LMWH) throughout pregnancy — improves live birth rate significantly."]','A','APS pregnancy loss mechanism: placental thrombosis + impaired trophoblast invasion. 2nd trimester loss is more characteristic of APS than 1st trimester (chromosomal anomalies). LMWH + aspirin is standard treatment in pregnancy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','medium','flashcard','What is the laboratory approach to diagnosing thrombophilia?','["Recommended investigations after unprovoked VTE or clinical suspicion:\n1. Factor V Leiden: APC resistance assay (screened); PCR/genetic testing (confirmed)\n2. Prothrombin G20210A mutation: PCR-based genetic testing\n3. Protein C activity: functional assay (affected by warfarin — test OFF anticoagulation)\n4. Protein S activity/antigen: affected by warfarin and pregnancy\n5. Antithrombin III activity: affected by heparin and acute thrombosis\n6. Antiphospholipid antibodies: lupus anticoagulant (clot-based test), anticardiolipin IgG/IgM, anti-β₂GPI — must be positive on TWO occasions ≥12 weeks apart\n7. Homocysteine level\nTiming: test 3 months AFTER the acute event; NOT while on anticoagulation (affects protein C, S, AT III)."]','A','Key rule: test for inherited thrombophilia AFTER completing anticoagulation and 3+ months post-event. Acute thrombosis and anticoagulants falsely lower protein C, S, and AT III. APS requires two positive tests ≥12 weeks apart.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Haematology','Pathology','Thrombophilia & VTE','hard','flashcard','What is the pathology of a deep vein thrombosis and how does it evolve?','["DVT thrombi form in the valve pockets of deep veins of the calf (most common origin) where flow is most stagnant. Lines of Zahn (alternating pale platelet-fibrin layers and dark red cell layers) are present in thrombi that form antemortem in flowing blood — distinguishing them from postmortem clots (uniform, gelatinous, no lines). DVT evolution: 1. Propagation: thrombus may extend proximally into popliteal, femoral, or iliac veins (increasing PE risk); 2. Embolisation: PE — the feared complication; 3. Dissolution: plasmin-mediated thrombolysis; 4. Organisation and recanalisation: fibroblast ingrowth → fibrous scar → partial luminal recanalisation → post-thrombotic syndrome (chronic venous insufficiency, oedema, skin ulceration)."]','A','Lines of Zahn = antemortem thrombus. Post-thrombotic syndrome occurs after DVT due to valve destruction and recanalisation — causes chronic lower limb oedema, pain, and skin changes. Proximal DVT has higher PE risk than isolated calf DVT.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
